const errores = [];

function minutos(hora) {
  const [h, m] = String(hora || '').split(':').map(Number);
  return h * 60 + m;
}

function fechaValida(valor) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(String(valor || ''))) return false;
  const [y, m, day] = valor.split('-').map(Number);
  const prueba = new Date(Date.UTC(y, m - 1, day));
  return prueba.getUTCFullYear() === y && prueba.getUTCMonth() === m - 1 && prueba.getUTCDate() === day;
}

function isoFecha(y, m, day) {
  return String(y).padStart(4, '0') + '-' + String(m).padStart(2, '0') + '-' + String(day).padStart(2, '0');
}

function lunesNumero(anio, mes, numero) {
  const primero = new Date(Date.UTC(anio, mes - 1, 1));
  const desplazamiento = (8 - primero.getUTCDay()) % 7;
  return isoFecha(anio, mes, 1 + desplazamiento + (numero - 1) * 7);
}

function esFeriadoMexico(fecha) {
  const [anio] = fecha.split('-').map(Number);
  const fijos = new Set([
    isoFecha(anio, 1, 1),
    lunesNumero(anio, 2, 1),
    lunesNumero(anio, 3, 3),
    isoFecha(anio, 5, 1),
    isoFecha(anio, 9, 16),
    lunesNumero(anio, 11, 3),
    isoFecha(anio, 12, 25)
  ]);
  if (anio % 6 === 2) fijos.add(isoFecha(anio, 10, 1));
  return fijos.has(fecha);
}

function crearSlots(inicio, fin) {
  const resultado = [];
  for (let actual = minutos(inicio), ultimo = minutos(fin); actual <= ultimo; actual += 40) {
    const h = Math.floor(actual / 60);
    const m = actual % 60;
    resultado.push(String(h).padStart(2, '0') + ':' + String(m).padStart(2, '0'));
  }
  return resultado;
}

